<section class="sl-card flush cn-t"><div class="row between wrap g8" style="padding:16px 18px"><div><h2 class="sl-ct">What to tell me</h2><span class="mut sm">Tick the channels you want for each update</span></div><div class="sl-seg boxed"><button type="button" data-sl-action="<?= $ep ?>" data-p-op="preset" data-p-preset="all" data-sl-reload>Everything</button><button type="button" data-sl-action="<?= $ep ?>" data-p-op="preset" data-p-preset="key" data-sl-reload>Only important</button><span class="sl-badge" aria-label="Choose individual updates below">Custom</span></div></div>
<div class="sl-tw"><table class="sl-table"><thead><tr><th>Update</th><th style="text-align:center">WhatsApp</th><th style="text-align:center">SMS</th><th style="text-align:center">E-mail</th></tr></thead><tbody>
<?php foreach ((array) sl_get($d, 'evs', []) as $e): ?><tr><td><span class="col"><span class="fw5"><?= sl_v($e, 'n') ?></span><span class="mut" style="font-size:12.5px"><?= sl_v($e, 'd') ?></span></span></td><?php foreach (['whatsapp' => ['wa', 'WhatsApp'], 'sms' => ['sms', 'SMS'], 'email' => ['em', 'E-mail']] as $ch => [$k, $lbl]): $disabled = !$chOn[$ch] || $paused; ?><td><span class="cn-ch"><button type="button" class="sl-chk <?= $disabled ? '' : sl_v($e, $k) ?>" role="checkbox" aria-checked="<?= $disabled ? 'false' : sl_v($e, $k . 'A') ?>" aria-label="<?= h($lbl) ?> for <?= sl_v($e, 'n') ?>" data-sl-chk-save="<?= $ep ?>" data-channel="<?= $ch ?>" data-event="<?= sl_v($e, 'key') ?>" <?= $disabled ? 'disabled title="' . ($paused ? 'Messages are paused' : h($lbl) . ' is off') . '" style="opacity:.45"' : '' ?>></button></span></td><?php endforeach; ?></tr><?php endforeach; ?>
</tbody></table></div><div class="row between wrap g8 sm" style="padding:12px 18px;border-top:1px solid var(--line)"><span class="mut">Security codes (log-in and pickup codes) are always sent so nobody else can collect your parcel.</span><span class="mono"><?= sl_v($d, 'costNote') ?></span></div></section>
