<section class="sl-card col g12"><h2 class="sl-ct">Offers and news</h2><div class="row between"><span class="col"><span>Promotions and holiday rates</span><span class="mut sm">Special prices when we run them</span></span><span class="<?= $tog((bool) sl_get($d, 'promo')) ?>" role="switch" aria-checked="<?= sl_get($d, 'promo') ? 'true' : 'false' ?>" aria-label="Promotions" data-sl-save="<?= $ep ?>" data-p-op="pref" data-p-key="notif_promo"></span></div><div class="row between"><span class="col"><span>Newsletter</span><span class="mut sm">Once a month by e-mail</span></span><span class="<?= $tog((bool) sl_get($d, 'news')) ?>" role="switch" aria-checked="<?= sl_get($d, 'news') ? 'true' : 'false' ?>" aria-label="Newsletter" data-sl-save="<?= $ep ?>" data-p-op="newsletter"></span></div></section>
